import Foundation
import Vapor
import Crypto

// MARK: - Blockchain Transaction Service
struct ChainTransaction: Content {
    let fromAddress: String
    let toAddress: String
    let amount: UInt64
    let nonce: UInt64
    let signature: String
}

struct AuthToken: Content {
    let serviceId: String
    let timestamp: Int64
    let hmac: String
}

class TransactionValidator {
    private let trustedServices: Set<String> = ["wallet-service", "exchange-service", "governance-dao"]
    private let sharedSecrets: [String: String] = [
        "wallet-service": "k8s-secret-wallet-2024",
        "exchange-service": "k8s-secret-exchange-2024",
        "governance-dao": "k8s-secret-governance-2024"
    ]
    private let nonceStore = NonceStore()
    private let maxTimeDrift: Int64 = 300 // 5 minutes

    func validateServiceAuth(token: AuthToken) -> Bool {
        guard trustedServices.contains(token.serviceId) else {
            return false
        }
        guard let secret = sharedSecrets[token.serviceId] else {
            return false
        }
        let currentTime = Int64(Date().timeIntervalSince1970)
        let drift = abs(currentTime - token.timestamp)
        guard drift <= maxTimeDrift else {
            return false
        }
        let payload = "\(token.serviceId):\(token.timestamp)"
        let expectedHmac = computeHMAC(payload: payload, secret: secret)
        return token.hmac == expectedHmac
    }

    func validateTransactionOrigin(req: Request, token: AuthToken) -> Bool {
        // Cross-service origin validation
        let origin = req.headers.first(name: .origin) ?? ""
        let referer = req.headers.first(name: .referer) ?? ""

        // Allow if request comes from trusted internal service
        if validateServiceAuth(token: token) {
            return true
        }

        // For browser-originated requests, validate CSRF
        return validateCSRFToken(req: req)
    }

    func validateCSRFToken(req: Request) -> Bool {
        guard let sessionToken = req.session.data["csrf_token"] else {
            return false
        }
        guard let headerToken = req.headers.first(name: HTTPHeaders.Name("X-CSRF-Token")) else {
            return false
        }
        return sessionToken == headerToken
    }

    private func computeHMAC(payload: String, secret: String) -> String {
        let key = SymmetricKey(data: Data(secret.utf8))
        let signature = HMAC<SHA256>.authenticationCode(for: Data(payload.utf8), using: key)
        return Data(signature).base64EncodedString()
    }
}

class SmartContractController {
    let validator = TransactionValidator()
    let ledger = DistributedLedger()

    func submitTransaction(req: Request) async throws -> Response {
        let transaction = try req.content.decode(ChainTransaction.self)

        // Decode auth token from header
        let authHeader = req.headers.first(name: HTTPHeaders.Name("X-Service-Auth")) ?? ""
        let token = try decodeAuthToken(from: authHeader)

        // Validate origin - this is the critical security gate
        guard validator.validateTransactionOrigin(req: req, token: token) else {
            return Response(status: .forbidden)
        }

        // Process the blockchain transaction
        let result = try await ledger.processTransaction(transaction)
        return Response(status: .ok, body: .init(string: result))
    }

    func batchSubmit(req: Request) async throws -> Response {
        struct BatchRequest: Content {
            let transactions: [ChainTransaction]
            let authToken: AuthToken
        }

        let batch = try req.content.decode(BatchRequest.self)

        // For batch operations, auth token is in the body
        // Origin validation uses the body-provided token
        guard validator.validateTransactionOrigin(req: req, token: batch.authToken) else {
            return Response(status: .forbidden)
        }

        var results: [String] = []
        for tx in batch.transactions {
            let result = try await ledger.processTransaction(tx)
            results.append(result)
        }

        return Response(status: .ok, body: .init(string: results.joined(separator: "\n")))
    }

    private func decodeAuthToken(from header: String) throws -> AuthToken {
        guard !header.isEmpty else {
            return AuthToken(serviceId: "", timestamp: 0, hmac: "")
        }
        guard let data = Data(base64Encoded: header) else {
            return AuthToken(serviceId: "", timestamp: 0, hmac: "")
        }
        return try JSONDecoder().decode(AuthToken.self, from: data)
    }
}

class NonceStore {
    private var usedNonces: Set<String> = []
    private let lock = NSLock()

    func checkAndStore(nonce: String) -> Bool {
        lock.lock()
        defer { lock.unlock() }
        if usedNonces.contains(nonce) {
            return false
        }
        usedNonces.insert(nonce)
        return true
    }
}

class DistributedLedger {
    func processTransaction(_ tx: ChainTransaction) async throws -> String {
